# shellcheck shell=bash
# Cache size monitoring: loams-ci-monitor.timer runs monitor.sh (root) every 15
# minutes. It records sizes for status.sh and logs the health report; a failed
# check fails the unit (`systemctl --failed`, `journalctl -u loams-ci-monitor`).

setup_monitor() {
  install -m 755 "$HERE/status.sh" /opt/loams-ci/bin/loams-ci-status
  install -m 755 "$HERE/monitor.sh" /opt/loams-ci/bin/monitor.sh
  ln -sfn /opt/loams-ci/bin/loams-ci-status /opt/loams-ci/bin/status.sh
  write_unit loams-ci-monitor.service <<EOF2
# Generated by deploy/ci-hosts/setup-host.sh.
[Unit]
Description=Loams local CI: record cache sizes and check health

[Service]
Type=oneshot
Nice=19
IOSchedulingClass=idle
ExecStart=/opt/loams-ci/bin/monitor.sh $DATA_ROOT
EOF2
  write_unit loams-ci-monitor.timer <<'EOF2'
# Generated by deploy/ci-hosts/setup-host.sh.
[Unit]
Description=Loams local CI: health and cache sizes every 15 minutes

[Timer]
OnBootSec=3min
OnUnitActiveSec=15min

[Install]
WantedBy=timers.target
EOF2
  systemctl enable -q --now loams-ci-monitor.timer
  systemctl start loams-ci-monitor.service || warn "the first health check reported a problem: /opt/loams-ci/bin/loams-ci-status"
}
